import {placeForAirport} from './localities.js?v=13';
const sites={G3:{name:'GOL',url:'https://b2c.voegol.com.br/compra'},TP:{name:'TAP',url:'https://www.flytap.com/'},AF:{name:'Air France',url:'https://www.airfrance.com.br/'}};
export function safeSellerUrl(raw){try{const u=new URL(raw);if(u.protocol!=='https:'||u.username||u.password||u.port)return null;return u;}catch{return null;}}
export const isGoogleBooking=u=>{const url=typeof u==='string'?safeSellerUrl(u):u;return !!url&&(/(^|\.)google\.[a-z.]+$/.test(url.hostname)||url.hostname==='googleadservices.com');};
function validTrip(q){const date=s=>typeof s==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(s)&&!Number.isNaN(Date.parse(s))&&new Date(s).toISOString().slice(0,10)===s;return q&&/^[A-Z]{3}$/.test(q.origin)&&/^[A-Z]{3}$/.test(q.destination)&&q.origin!==q.destination&&date(q.depart)&&date(q.return)&&q.return>=q.depart;}
export function sellerForOffer(offer,trip){if(!validTrip(trip)||!Array.isArray(offer?.flights)||offer.flights.length!==2)return null;const [out,back]=offer.flights;if(!out.legs?.length||!back.legs?.length||out.legs[0].origin!==trip.origin||out.legs.at(-1).dest!==trip.destination||out.legs[0].depDate!==trip.depart||back.legs[0].origin!==trip.destination||back.legs.at(-1).dest!==trip.origin||back.legs[0].depDate!==trip.return)return null;const carriers=new Set(offer.flights.flatMap(f=>f.legs.map(l=>l.airline)));if(carriers.size!==1)return null;const code=[...carriers][0];
 if(code==='AD'){const url=new URL('https://www.voeazul.com.br/br/pt/home/selecao-voo'),usDate=s=>s.slice(5,7)+'/'+s.slice(8,10)+'/'+s.slice(0,4);for(const [key,value] of Object.entries({'c[0].ds':trip.origin,'c[0].std':usDate(trip.depart),'c[0].as':trip.destination,'c[1].ds':trip.destination,'c[1].std':usDate(trip.return),'c[1].as':trip.origin,'p[0].t':'ADT','p[0].c':'2','p[0].cp':'false','f.dl':'3','f.dr':'3','cc':'BRL'}))url.searchParams.set(key,value);return {name:'Azul',url:url.href,kind:'search'};}
 if(code==='LA'){const originCountry=placeForAirport(trip.origin)?.country,destinationCountry=placeForAirport(trip.destination)?.country;if(!originCountry||!destinationCountry)return null;const airport=(iata,country)=>({id:`${iata}_${country}_AIRPORT`,iata,type:'AIRPORT',airportIataCode:iata});const data={tripTypeSelected:{value:'RT'},cabinSelected:{label:'Economy',value:'Economy'},passengerSelected:{adultQuantity:2,childrenQuantity:0,infantQuantity:0},originSelected:airport(trip.origin,originCountry),destinationSelected:airport(trip.destination,destinationCountry),dateGoSelected:trip.depart,dateReturnSelected:trip.return};const url=new URL('https://www.latamairlines.com/br/pt/oferta-voos');url.searchParams.set('dataFlight',JSON.stringify(data));url.searchParams.set('sort','PRICE,asc');return {name:'LATAM',url:url.href,kind:'search'};}
 return sites[code]?{...sites[code],kind:'site'}:null;
}
export function sellerExplanation(buy){if(buy?.kind==='search')return `Abre a seleção de voos da ${buy.name} com trecho, datas e 2 adultos. Selecione os voos e confirme a tarifa na companhia.`;if(buy?.kind==='site')return `Abre o site oficial da ${buy.name}. Será necessário informar o trecho e confirmar a tarifa no vendedor.`;return 'Abre diretamente o link do vendedor registrado para esta oferta. Confirme a tarifa e a disponibilidade antes de pagar.';}
